    Bug 1979295 - Use folder localizedName for folder.prettyPath which ends up in Location column. r=darktrojan

    Differential Revision: https://phabricator.services.mozilla.com/D261727

diff --git a/mailnews/base/src/nsMsgDBFolder.cpp b/mailnews/base/src/nsMsgDBFolder.cpp
index 8670240c67c..2c0d36a6c95 100644
--- a/mailnews/base/src/nsMsgDBFolder.cpp
+++ b/mailnews/base/src/nsMsgDBFolder.cpp
@@ -3035,10 +3035,10 @@ NS_IMETHODIMP nsMsgDBFolder::GetPrettyPath(nsACString& aPath) {
       aPath.AppendLiteral("/");
     }
   }
-  nsCString name;
-  rv = GetName(name);
+  nsCString localizedName;
+  rv = GetLocalizedName(localizedName);
   NS_ENSURE_SUCCESS(rv, rv);
-  aPath.Append(name);
+  aPath.Append(localizedName);
   return NS_OK;
 }

